import { applyDemoEvent, createDemoDay, DemoError } from './field-demo-model.mjs';
export const DEMO_COOKIE = 'opwp_field_demo';
export const DEMO_TTL = 7 * 24 * 60 * 60;
// Test-provider receipts are generated by the backend only. Never treat an
// offline action or an HTTP acceptance as proof of real SMS delivery.
export function demoReceipt(notification,receivedAt,now=Date.now()) {
  const stale=notification.type==='on_way'&&receivedAt>=Date.parse(notification.at)+notification.minutes*60000;
  const status=stale?'expired':notification.scenario==='failure'?'failed':notification.scenario==='no_receipt'?(now-receivedAt>=60000?'unconfirmed':'pending'):'delivered';
  return {id:notification.id,stopId:notification.stopId,type:notification.type,status,simulated:true,checkedAt:new Date(now).toISOString(),receivedAt:new Date(receivedAt).toISOString(),report:['failed','expired','unconfirmed'].includes(status),detail:stale?'Arrival window passed while offline. Follow up with the client.':status==='failed'?'Test provider rejected the text. Office follow-up required.':status==='unconfirmed'?'No delivery receipt after one minute. Check with the client.':status==='pending'?'Accepted by the test provider; waiting for delivery confirmation.':'Test provider confirmed delivery. No real text was sent.'};
}
export async function demoReceipts(db,session,now=Date.now()) {
  const day=JSON.parse(session.state_json);
  const rows=await db.prepare('SELECT id,received_at FROM field_demo_events WHERE session_id=? ORDER BY sequence LIMIT 1500').bind(session.id).all();
  const received=new Map(rows.results.map(row=>[row.id,row.received_at]));
  return (day.notifications||[]).filter(n=>received.has(n.id)).map(n=>demoReceipt(n,received.get(n.id),now));
}
export async function demoHash(value) {
  const bytes = typeof value === 'string' ? new TextEncoder().encode(value) : value;
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)), b=>b.toString(16).padStart(2,'0')).join('');
}
export async function demoSession(db, headers, now=Date.now()) {
  const token = (headers.get('cookie') || '').split(';').map(v=>v.trim()).find(v=>v.startsWith(`${DEMO_COOKIE}=`))?.slice(DEMO_COOKIE.length+1);
  if (!token || !/^[a-f\d]{64}$/.test(token)) return null;
  return db.prepare('SELECT * FROM field_demo_sessions WHERE token_hash=? AND expires_at>?').bind(await demoHash(token),now).first();
}
export async function startDemoSession(db, now=Date.now()) {
  const token = Array.from(crypto.getRandomValues(new Uint8Array(32)), b=>b.toString(16).padStart(2,'0')).join('');
  const id=crypto.randomUUID(),day=createDemoDay(now);
  // Bounded opportunistic retention cleanup, also cascades to demo-only photos/events.
  await db.prepare('DELETE FROM field_demo_sessions WHERE id IN (SELECT id FROM field_demo_sessions WHERE expires_at<? LIMIT 30)').bind(now).run();
  await db.prepare('INSERT INTO field_demo_sessions(id,token_hash,state_json,created_at,expires_at) VALUES (?,?,?,?,?)').bind(id,await demoHash(token),JSON.stringify(day),now,now+DEMO_TTL*1000).run();
  return {id,token,day,expiresAt:now+DEMO_TTL*1000};
}
export async function saveDemoEvent(db, session, event, now=Date.now()) {
  if(!event || typeof event!=='object' || !/^[a-f\d-]{36}$/i.test(event.id||''))throw new DemoError('Invalid demo action.');
  const hash=await demoHash(JSON.stringify(event));
  const prior=await db.prepare('SELECT body_hash FROM field_demo_events WHERE session_id=? AND id=?').bind(session.id,String(event?.id||'')).first();
  if(prior) { if(prior.body_hash!==hash) throw new DemoError('An action identifier was reused with different content.',409); return {sequence:event.sequence,replayed:true}; }
  if(event?.sequence!==session.revision+1) throw new DemoError('Demo sync order changed. Your local work is retained; export it before resetting.',409);
  const day=applyDemoEvent(JSON.parse(session.state_json),event,{now});
  if(event.type==='add_photo') {
    const photo=await db.prepare('SELECT id FROM field_demo_photos WHERE session_id=? AND id=? AND task_id=?').bind(session.id,event.body.photoId,event.body.taskId).first();
    if(!photo) throw new DemoError('The photo must be uploaded before its job action.',409);
  }
  try { await db.prepare('INSERT INTO field_demo_events(session_id,id,sequence,body_hash,event_json,result_json,received_at) VALUES (?,?,?,?,?,?,?)').bind(session.id,event.id,event.sequence,hash,JSON.stringify(event),JSON.stringify(day),now).run(); }
  catch {
    const replay=await db.prepare('SELECT body_hash FROM field_demo_events WHERE session_id=? AND id=?').bind(session.id,event.id).first();
    if(replay?.body_hash===hash) return {sequence:event.sequence,replayed:true};
    throw new DemoError('Demo sync order changed. Your work remains on this phone.',409);
  }
  const notification=day.notifications.find(n=>n.id===event.id);
  return {sequence:event.sequence,replayed:false,receipt:notification?demoReceipt(notification,now,now):null};
}
